import json
res = json.load(open('sweep_starts.json'))

def cells(r):
    W,H=r['got']
    prod=r['prod']; strn=r['strn']
    return W,H,prod,strn

def eq_at(prod,strn,W,H,x,y,x2,y2):
    return prod[y%H][x%W]==prod[y2%H][x2%W] and strn[y%H][x%W]==strn[y2%H][x2%W]

def test_transform(r, f):
    W,H,prod,strn = cells(r)
    bad=0
    for y in range(H):
        for x in range(W):
            x2,y2 = f(x,y,W,H)
            if not eq_at(prod,strn,W,H,x,y,x2,y2):
                bad+=1
    return bad==0

def translations(r):
    W,H,prod,strn = cells(r)
    good=[]
    for dy in range(H):
        for dx in range(W):
            if dx==0 and dy==0: continue
            if test_transform(r, lambda x,y,W,H,dx=dx,dy=dy: (x+dx,y+dy)):
                good.append((dx,dy))
    return good

for n in (2,3,4,5,6):
    print(f'==== n={n} ====')
    for r in res:
        if r['n']!=n: continue
        if r['seed'] not in (1,2,5): continue
        if r['req'] not in ([20,20],[9,9],[10,10],[24,24],[12,12],[15,15],[30,30]): continue
        W,H=r['got']
        tr = translations(r)
        syms = []
        if test_transform(r, lambda x,y,W,H:(W-1-x,y)): syms.append('flipX')
        if test_transform(r, lambda x,y,W,H:(x,H-1-y)): syms.append('flipY')
        if test_transform(r, lambda x,y,W,H:(W-1-x,H-1-y)): syms.append('rot180')
        # glide: flip then half-shift
        if test_transform(r, lambda x,y,W,H:(W-1-x,y+H//2)): syms.append('glideX(flipY? x-flip+y-half)')
        if test_transform(r, lambda x,y,W,H:(x+W//2,H-1-y)): syms.append('glideY(x-half+y-flip)')
        print(r['seed'], r['req'], (W,H), 'translations:', tr, 'other:', syms)
